import{_ as o,C as r,c as s,o as i,a3 as n,G as a}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Maintenance calendar","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/calendar/maintenance-calendar.md","filePath":"master/supply-chain/maintenance/calendar/maintenance-calendar.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/maintenance/calendar/maintenance-calendar.md"};function c(h,e,d,u,g,m){const t=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=n('<h1 id="maintenance-calendar" tabindex="-1">Maintenance calendar <a class="header-anchor" href="#maintenance-calendar" aria-label="Permalink to &quot;Maintenance calendar&quot;">​</a></h1><p>The calendar shows every maintenance request that has a scheduled date. Maintenance comes in two kinds. Corrective maintenance fixes something that broke, such as an oil leak. Preventive maintenance is planned in advance, such as a monthly lubrication. The calendar lets you see both on one grid, so you can spread the work and avoid busy days.</p><blockquote><p><strong>In simple words:</strong> The calendar is a wall planner. Each block is a request on its scheduled day.</p></blockquote><p>Path: <code>Maintenance → Maintenance Calendar</code></p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Only requests with a <strong>Scheduled Date</strong> show up. Stages and teams are set up in <a href="./../setup/stages.html">Stages</a> and <a href="./../setup/maintenance-teams.html">Maintenance teams</a>.</p></div><h2 id="open-the-calendar" tabindex="-1">Open the calendar <a class="header-anchor" href="#open-the-calendar" aria-label="Permalink to &quot;Open the calendar&quot;">​</a></h2><ol><li>Click <strong>Maintenance</strong> in the top menu.</li><li>Click <strong>Maintenance Calendar</strong> in the left menu.</li></ol><p>The calendar opens in the <strong>Month</strong> view. Weeks start on Monday.</p>',8)),a(t,{src:"/images1/maintenance/cal_month_view.png",alt:"Maintenance Calendar in Month view for October 2026 with Hydraulic press oil leak and Monthly lubrication in green on Oct 14 and Oct 20, and Quarterly safety inspection in blue on Oct 16"}),e[1]||(e[1]=n('<h2 id="views-and-controls" tabindex="-1">Views and controls <a class="header-anchor" href="#views-and-controls" aria-label="Permalink to &quot;Views and controls&quot;">​</a></h2><p>The toolbar has the previous and next arrows, <strong>Today</strong>, the current period title, and the view buttons. The green <strong>New Request</strong> button sits above it at the top right. Use the arrows to move in time. Click <strong>Today</strong> to jump back. It stays greyed out while the current period is already shown.</p><ul><li><strong>Year:</strong> Shows 12 small month grids. It does not show events.</li><li><strong>Month:</strong> Shows one month as a grid. This is the default view.</li><li><strong>Week:</strong> Shows seven days on an hourly grid from 12am to 11pm. Each block is one hour tall from its start time.</li><li><strong>List:</strong> Shows the week as a list of requests, each with a coloured dot. It reads &quot;No events to display&quot; when the week is empty.</li></ul>',3)),a(t,{src:"/images1/maintenance/cal_year_view.png",alt:"Calendar in Year view for 2026 showing the first four month grids with no events"}),a(t,{src:"/images1/maintenance/cal_week_view.png",alt:"Calendar in Week view for Oct 12 to 18, 2026 with a green block on Oct 14 and a blue block on Oct 16"}),a(t,{src:"/images1/maintenance/cal_list_view.png",alt:"Calendar in List view for Oct 12 to 18, 2026 with Wed Oct 14 (green dot) and Fri Oct 16 (blue dot)"}),e[2]||(e[2]=n('<h2 id="event-colours" tabindex="-1">Event colours <a class="header-anchor" href="#event-colours" aria-label="Permalink to &quot;Event colours&quot;">​</a></h2><p>The colour shows the stage of the request:</p><ul><li><strong>Blue:</strong> The request is in a stage that is not marked <strong>Done</strong>, for example <strong>New Request</strong> or <strong>In Progress</strong>.</li><li><strong>Green:</strong> The request is in a stage marked <strong>Done</strong>, for example <strong>Repaired</strong>.</li></ul><p>Titles are cut short in month cells. The week, list and pop-up show the full title.</p><p>When a request moves to a Done stage, its block turns green. See <a href="./../setup/stages.html">Stages</a>.</p>',5)),a(t,{src:"/images1/maintenance/cal_event_colours.png",alt:"Calendar showing green requests on Oct 14 and Oct 20 and a blue request on Oct 16"}),e[3]||(e[3]=n('<h2 id="open-a-request-from-the-calendar" tabindex="-1">Open a request from the calendar <a class="header-anchor" href="#open-a-request-from-the-calendar" aria-label="Permalink to &quot;Open a request from the calendar&quot;">​</a></h2><ol><li>Click an event, for example <strong>Hydraulic press oil leak</strong>.</li><li>A window with the request subject as its heading opens. It shows <strong>Date</strong>, <strong>Time</strong> (for example 09:00 - 11:00 (02:00)), <strong>Technician</strong>, <strong>Priority</strong>, <strong>Maintenance Type</strong> and <strong>Stage</strong>.</li><li>Click <strong>Edit</strong> to open the full request form. Click <strong>Cancel</strong>, the close button or press Escape to close the window.</li></ol>',2)),a(t,{src:"/images1/maintenance/cal_event_view_popup.png",alt:"Pop-up for Hydraulic press oil leak showing Date Oct 14, 2026, Time 09:00 - 11:00 (02:00), Technician, Priority, Maintenance Type and Stage, with Edit and Cancel buttons"}),e[4]||(e[4]=n('<h2 id="create-a-request-from-the-calendar" tabindex="-1">Create a request from the calendar <a class="header-anchor" href="#create-a-request-from-the-calendar" aria-label="Permalink to &quot;Create a request from the calendar&quot;">​</a></h2><p>Use this for a quick request. You add the details later on the full form.</p><ol><li>Click an empty date, or click <strong>New Request</strong> at the top right. A window titled <strong>New Maintenance Request</strong> opens.</li><li>Type the <strong>Subject</strong>. Required. Use <code>Hydraulic press oil leak</code>.</li><li>If you used <strong>New Request</strong>, check <strong>Scheduled At</strong>. Required. It is filled with the current date and time, for example &quot;Oct 13, 2026 11:04&quot;. Set it to tomorrow 09:00. If you clicked a date, the window has only <strong>Subject</strong>, and that date is used.</li><li>Click <strong>Create</strong>, or <strong>Create &amp; create another</strong> to add more.</li></ol>',3)),a(t,{src:"/images1/maintenance/cal_click_date_modal.png",alt:"New Maintenance Request window opened from a date, with only the Subject field and the Create, Create & create another and Cancel buttons"}),a(t,{src:"/images1/maintenance/cal_new_request_modal.png",alt:"New Maintenance Request window from the New Request button with the Subject and Scheduled At fields"}),e[5]||(e[5]=n('<p>The new request gets these values automatically:</p><ul><li><strong>Maintenance Type:</strong> Corrective.</li><li><strong>Stage:</strong> The first stage, for example <strong>New Request</strong>.</li><li><strong>Responsible:</strong> You.</li><li><strong>Team:</strong> The first team of your company.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Open the new request afterwards and pick the equipment. The category, team and technician then update from the equipment. See <a href="./../requests/create-request.html">Create a maintenance request</a>.</p></div><h2 id="plan-with-the-calendar" tabindex="-1">Plan with the calendar <a class="header-anchor" href="#plan-with-the-calendar" aria-label="Permalink to &quot;Plan with the calendar&quot;">​</a></h2><ol><li>Open the <strong>Month</strong> view and look for days with many blocks.</li><li>Switch to <strong>Week</strong> to compare durations on a busy day.</li><li>Click a block, then <strong>Edit</strong>, and change the scheduled date to move a request to a quieter day.</li><li>Plan recurring work with <a href="./../requests/preventive-maintenance.html">Preventive maintenance</a>. Each repeat shows up on its date.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../requests/create-request.html">Create a maintenance request</a></li><li><a href="./../requests/request-list.html">Request list</a></li><li><a href="./../requests/preventive-maintenance.html">Preventive maintenance</a></li><li><a href="./../setup/stages.html">Stages</a></li></ul>',7))])}const w=o(l,[["render",c]]);export{_ as __pageData,w as default};
